const search = `-- name: Search :many

(SELECT 'company'::text AS type, id, name AS title, COALESCE(domain, '') AS subtitle
   FROM companies
  WHERE companies.workspace_id = $1 AND archived_at IS NULL
    AND (name ILIKE '%' || $2::text || '%' OR domain ILIKE '%' || $2::text || '%')
  LIMIT $3)
UNION ALL
(SELECT 'contact', id, trim(first_name || ' ' || last_name), COALESCE(email, '')
   FROM contacts
  WHERE contacts.workspace_id = $1 AND archived_at IS NULL
    AND ((first_name || ' ' || last_name) ILIKE '%' || $2::text || '%' OR email ILIKE '%' || $2::text || '%')
  LIMIT $3)
UNION ALL
(SELECT 'opportunity', id, title, status
   FROM opportunities
  WHERE opportunities.workspace_id = $1 AND archived_at IS NULL
    AND title ILIKE '%' || $2::text || '%'
  LIMIT $3)
`

type SearchParams struct {
	WorkspaceID uuid.UUID `json:"workspace_id"`
	Query       string    `json:"query"`
	Lim         int32     `json:"lim"`
}

type SearchRow struct {
	Type     string    `json:"type"`
	ID       uuid.UUID `json:"id"`
	Title    string    `json:"title"`
	Subtitle string    `json:"subtitle"`
}

// ───────────── search ─────────────
func (q *Queries) Search(ctx context.Context, arg SearchParams) ([]SearchRow, error) {
	rows, err := q.db.Query(ctx, search, arg.WorkspaceID, arg.Query, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchRow{}
	for rows.Next() {
		var i SearchRow
		if err := rows.Scan(
			&i.Type,
			&i.ID,
			&i.Title,
			&i.Subtitle,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const timeline = `-- name: Timeline :many
SELECT 'interaction'::text AS kind, i.id, i.occurred_at AS at, i.type AS label, i.direction AS detail,
       i.subject, i.summary, i.opportunity_id
FROM interactions i
WHERE i.workspace_id = $2
  AND (($3::uuid IS NOT NULL AND i.opportunity_id = $3)
    OR ($4::uuid IS NOT NULL AND i.contact_id = $4)
    OR ($5::uuid IS NOT NULL AND i.company_id = $5))
UNION ALL
SELECT 'stage_change'::text, sc.id, sc.changed_at, sc.to_stage_name, sc.to_category,
       sc.from_stage_name, sc.reason, sc.opportunity_id
FROM stage_changes sc
JOIN opportunities o ON o.id = sc.opportunity_id
WHERE sc.workspace_id = $2
  AND (($3::uuid IS NOT NULL AND sc.opportunity_id = $3)
    OR ($4::uuid IS NOT NULL AND o.primary_contact_id = $4)
    OR ($5::uuid IS NOT NULL AND o.company_id = $5))
ORDER BY at DESC
LIMIT $1
`

type TimelineParams struct {
	Lim           int32      `json:"lim"`
	WorkspaceID   uuid.UUID  `json:"workspace_id"`
	OpportunityID *uuid.UUID `json:"opportunity_id"`
	ContactID     *uuid.UUID `json:"contact_id"`
	CompanyID     *uuid.UUID `json:"company_id"`
}

type TimelineRow struct {
	Kind          string     `json:"kind"`
	ID            uuid.UUID  `json:"id"`
	At            time.Time  `json:"at"`
	Label         string     `json:"label"`
	Detail        string     `json:"detail"`
	Subject       string     `json:"subject"`
	Summary       string     `json:"summary"`
	OpportunityID *uuid.UUID `json:"opportunity_id"`
}

// Timeline of one record: interactions and stage changes, newest first.
func (q *Queries) Timeline(ctx context.Context, arg TimelineParams) ([]TimelineRow, error) {
	rows, err := q.db.Query(ctx, timeline,
		arg.Lim,
		arg.WorkspaceID,
		arg.OpportunityID,
		arg.ContactID,
		arg.CompanyID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TimelineRow{}
	for rows.Next() {
		var i TimelineRow
		if err := rows.Scan(
			&i.Kind,
			&i.ID,
			&i.At,
			&i.Label,
			&i.Detail,
			&i.Subject,
			&i.Summary,
			&i.OpportunityID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const touchOpportunityInteraction = `-- name: TouchOpportunityInteraction :exec
UPDATE opportunities SET last_interaction_at = GREATEST(COALESCE(last_interaction_at, $3::timestamptz), $3::timestamptz)
WHERE workspace_id = $1 AND id = $2
`

type TouchOpportunityInteractionParams struct {
	WorkspaceID uuid.UUID `json:"workspace_id"`
	ID          uuid.UUID `json:"id"`
	At          time.Time `json:"at"`
}

func (q *Queries) TouchOpportunityInteraction(ctx context.Context, arg TouchOpportunityInteractionParams) error {
	_, err := q.db.Exec(ctx, touchOpportunityInteraction, arg.WorkspaceID, arg.ID, arg.At)
	return err
}
